let language: AppLanguage = "fr";
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function setAppLanguage(next: AppLanguage) {
  document.documentElement.lang = next;
  if (language === next) return;
  language = next;
  listeners.forEach((listener) => listener());
}

export function getAppLanguage() {
  return language;
}

export function localeForLanguage(value: AppLanguage) {
  return value === "en" ? "en-US" : "fr-FR";
}

function interpolate(template: string, params?: Params) {
  if (!params) return template;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g, (token, name: string) => String(params[name] ?? token));
}

export function translate(currentLanguage: AppLanguage, key: TranslationKey, params?: Params) {
  return interpolate((currentLanguage === "en" ? en : fr)[key] ?? fr[key], params);
}

export function useI18n() {
  const currentLanguage = useSyncExternalStore(subscribe, getAppLanguage, getAppLanguage);
  const t = useCallback((key: TranslationKey, params?: Params) => translate(currentLanguage, key, params), [currentLanguage]);
  return { language: currentLanguage, locale: localeForLanguage(currentLanguage), t };
}
